import type { EngineOp, RequestMessage, WorkerToMain } from './protocol';
import {
  EngineError,
  type AddBodiesResult,
  type BodyPatch,
  type EngineController,
  type EngineErrorCode,
  type EngineInfo,
  type EngineSnapshot,
  type LoadSceneOptions,
  type LoadSceneResult,
  type ObserverRequest,
  type SceneBodyJson,
  type Vec3,
} from './types';

export interface CreateEngineOptions {
  /** The app's base URL (Vite BASE_URL); the engine files are served from `${baseUrl}engine/`. Default './'. */
  baseUrl?: string;
  /** Rejects a request that has no answer after this many ms (default 60000). */
  requestTimeoutMs?: number;
}

interface Pending {
  resolve: (reply: Extract<WorkerToMain, { type: 'response'; ok: true }>) => void;
  reject: (error: EngineError) => void;
  timer: ReturnType<typeof setTimeout>;
}

class WorkerEngine implements EngineController {
  readonly ready: Promise<EngineInfo>;
  private readonly worker: Worker;
  private readonly pending = new Map<number, Pending>();
  private readonly listeners = new Set<(snapshot: EngineSnapshot) => void>();
  private readonly timeoutMs: number;
  private nextId = 1;
  private disposed = false;
  private fatal: EngineError | null = null;
  private lastSequence = 0;

  constructor(options: CreateEngineOptions) {
    this.timeoutMs = options.requestTimeoutMs ?? 60000;
    const base = new URL(options.baseUrl ?? './', document.baseURI).href;
    const engineUrl = new URL('engine/', base).href;
    this.worker = new Worker(new URL('./worker.ts', import.meta.url), { type: 'module', name: 'cosmic-engine' });
    let readyResolve: (info: EngineInfo) => void = () => undefined;
    let readyReject: (error: EngineError) => void = () => undefined;
    this.ready = new Promise<EngineInfo>((resolve, reject) => {
      readyResolve = resolve;
      readyReject = reject;
    });
    // Callers that never await ready still get each request's own rejection.
    this.ready.catch(() => undefined);
    this.worker.onmessage = (event: MessageEvent<WorkerToMain>) => {
      const message = event.data;
      switch (message.type) {
        case 'ready':
          readyResolve(message.info as EngineInfo);
          break;
        case 'fatal': {
          const error = new EngineError(message.code, message.message);
          this.fatal = error;
          readyReject(error);
          this.failAll(error);
          break;
        }
        case 'snapshot':
          this.publish(message.snapshot);
          break;
        case 'response': {
          const entry = this.pending.get(message.id);
          if (!entry) break;
          this.pending.delete(message.id);
          clearTimeout(entry.timer);
          if (message.ok) {
            if (message.snapshot) this.publish(message.snapshot);
            entry.resolve(message);
          } else {
            entry.reject(new EngineError(message.code, message.message));
          }
          break;
        }
      }
    };
    this.worker.onerror = (event: ErrorEvent) => {
      const error = new EngineError('engine_unavailable', `engine worker error: ${event.message}`);
      this.fatal = error;
      readyReject(error);
      this.failAll(error);
    };
    this.worker.postMessage({ type: 'init', engineUrl });
  }

  private failAll(error: EngineError): void {
    for (const [, entry] of this.pending) {
      clearTimeout(entry.timer);
      entry.reject(error);
    }
    this.pending.clear();
  }

  private publish(snapshot: EngineSnapshot): void {
    if (snapshot.sequence <= this.lastSequence) return;
    this.lastSequence = snapshot.sequence;
    for (const listener of this.listeners) {
      try {
        listener(snapshot);
      } catch (error) {
        console.error('engine snapshot listener failed', error);
      }
    }
  }

  private request(op: EngineOp, args: Record<string, unknown> = {}, bytes?: Uint8Array): Promise<Extract<WorkerToMain, { type: 'response'; ok: true }>> {
    if (this.disposed) return Promise.reject(new EngineError('disposed', 'the engine was disposed'));
    if (this.fatal) return Promise.reject(this.fatal);
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new EngineError('timeout', `engine request ${op} timed out after ${this.timeoutMs} ms`));
      }, this.timeoutMs);
      this.pending.set(id, { resolve, reject, timer });
      const message: RequestMessage = { type: 'request', id, op, args, bytes };
      this.worker.postMessage(message, bytes ? [bytes.buffer as ArrayBuffer] : []);
    });
  }

  private async snapshotOf(op: EngineOp, args: Record<string, unknown> = {}): Promise<EngineSnapshot> {
    const reply = await this.request(op, args);
    if (!reply.snapshot) throw new EngineError('protocol', `${op} returned no snapshot`);
    return reply.snapshot;
  }

  async loadScene(sceneDocument: string | object, options?: LoadSceneOptions): Promise<LoadSceneResult> {
    const scene = typeof sceneDocument === 'string' ? sceneDocument : JSON.stringify(sceneDocument);
    const reply = await this.request('loadScene', { scene, startPaused: options?.startPaused ?? true });
    if (!reply.snapshot) throw new EngineError('protocol', 'loadScene returned no snapshot');
    return { ...(reply.result as Omit<LoadSceneResult, 'snapshot'>), snapshot: reply.snapshot };
  }

  reset(): Promise<EngineSnapshot> {
    return this.snapshotOf('reset');
  }

  step(seconds: number, maxSteps = 4096): Promise<EngineSnapshot> {
    return this.snapshotOf('step', { seconds, maxSteps });
  }

  stepExact(steps: number): Promise<EngineSnapshot> {
    return this.snapshotOf('stepExact', { steps });
  }

  pause(): Promise<EngineSnapshot> {
    return this.snapshotOf('pause');
  }

  resume(): Promise<EngineSnapshot> {
    return this.snapshotOf('resume');
  }

  play(rate: number): Promise<EngineSnapshot> {
    return this.snapshotOf('play', { rate });
  }

  stop(): Promise<EngineSnapshot> {
    return this.snapshotOf('stop');
  }

  setBaseStep(seconds: number): Promise<EngineSnapshot> {
    return this.snapshotOf('setBaseStep', { seconds });
  }

  editBody(id: number, patch: BodyPatch, label?: string): Promise<EngineSnapshot> {
    return this.snapshotOf('editBody', { id, patch, label });
  }

  kick(id: number, deltaVelocity: Vec3, label?: string): Promise<EngineSnapshot> {
    return this.snapshotOf('kick', { id, deltaVelocity, label });
  }

  async addBodies(bodies: SceneBodyJson[], label?: string): Promise<AddBodiesResult> {
    const reply = await this.request('addBodies', { bodies, label });
    if (!reply.snapshot) throw new EngineError('protocol', 'addBodies returned no snapshot');
    return { createdIds: (reply.result as { createdIds: number[] }).createdIds, snapshot: reply.snapshot };
  }

  removeBodies(ids: number[], label?: string): Promise<EngineSnapshot> {
    return this.snapshotOf('removeBodies', { ids, label });
  }

  undo(): Promise<EngineSnapshot> {
    return this.snapshotOf('undo');
  }

  redo(): Promise<EngineSnapshot> {
    return this.snapshotOf('redo');
  }

  createBranch(name: string): Promise<EngineSnapshot> {
    return this.snapshotOf('createBranch', { name });
  }

  switchBranch(name: string): Promise<EngineSnapshot> {
    return this.snapshotOf('switchBranch', { name });
  }

  async addObserver(request: ObserverRequest): Promise<{ observerId: number; snapshot: EngineSnapshot }> {
    const reply = await this.request('addObserver', { ...request });
    if (!reply.snapshot) throw new EngineError('protocol', 'addObserver returned no snapshot');
    return { observerId: (reply.result as { observerId: number }).observerId, snapshot: reply.snapshot };
  }

  removeObserver(observerId: number): Promise<EngineSnapshot> {
    return this.snapshotOf('removeObserver', { observerId });
  }

  enableSurface(bodyId: number, latitudeBands?: number, longitudeCells?: number): Promise<EngineSnapshot> {
    return this.snapshotOf('enableSurface', { id: bodyId, latitudeBands, longitudeCells });
  }

  async save(): Promise<Uint8Array> {
    const reply = await this.request('save');
    if (!reply.bytes) throw new EngineError('protocol', 'save returned no bytes');
    return reply.bytes;
  }

  loadSave(bytes: Uint8Array): Promise<EngineSnapshot> {
    // The buffer is transferred to the worker: send a copy so the caller keeps its bytes.
    const copy = bytes.slice();
    return this.request('loadSave', {}, copy).then((reply) => {
      if (!reply.snapshot) throw new EngineError('protocol', 'loadSave returned no snapshot');
      return reply.snapshot;
    });
  }

  snapshot(): Promise<EngineSnapshot> {
    return this.snapshotOf('snapshot');
  }

  subscribe(listener: (snapshot: EngineSnapshot) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.worker.terminate();
    this.failAll(new EngineError('disposed', 'the engine was disposed'));
    this.listeners.clear();
  }
}

export function createWorkerEngine(options: CreateEngineOptions = {}): EngineController {
  return new WorkerEngine(options);
}

export type { EngineErrorCode };
