// Copyright (c) 2026 AiXenix.
//
// Units are SI throughout: metres, seconds, kilograms, watts, kelvin, radians. Positions and velocities are in the core's
// barycentric world frame. Rendering converts to AU and camera space; the engine never does.
//
// Every number crossing this API comes from the real core (CosmicCore). There is no JavaScript physics and no fallback
// simulation: if the WebAssembly module cannot load, every request rejects with an EngineError.

/** [x, y, z] in SI (m, m/s, or a unit vector). */
export type Vec3 = [number, number, number];

/** Core body kinds (cx::BodyKindName). */
export type BodyKind = 'planet' | 'star' | 'neutron_star' | 'pulsar' | 'black_hole' | 'agn' | 'fragment';

/** Core run states (cx::RunStateName). */
export type RunState = 'running' | 'user_paused' | 'guard_paused' | 'speed_paused' | 'faulted' | 'no_world';

/** Why a step call stopped (cx::StepLimitName). 'none' = it reached the requested time. */
export type StepLimit = 'none' | 'budget' | 'close_encounter' | 'guard' | 'speed_limit' | 'fault' | 'paused' | 'event';

/** Core result codes (cx::CoreResultName) plus the bridge's own codes. */
export type EngineErrorCode =
  | 'invalid_argument' | 'not_found' | 'overlap' | 'capacity_exceeded' | 'out_of_domain' | 'stale_revision' | 'paused'
  | 'corrupt' | 'incompatible' | 'not_applicable'
  | 'no_world' | 'scene_invalid' | 'nothing_to_undo' | 'nothing_to_redo' | 'busy' | 'engine_unavailable' | 'timeout'
  | 'protocol' | 'disposed';

/** Core event kinds (cx::EventKindName). */
export type EngineEventKind =
  | 'body_added' | 'body_removed' | 'body_edited' | 'merge' | 'fragmentation' | 'tracer_absorbed' | 'guard_pause'
  | 'guard_absorption' | 'speed_limit_exceeded' | 'domain_fault' | 'fuel_exhausted' | 'neutron_star_collapse_model_rule'
  | 'surface_removed' | 'profile_changed' | 'snapshot_restored' | 'transit_detected' | 'eclipse_detected'
  | 'light_front_arrived' | 'shell_arrived';

export class EngineError extends Error {
  readonly code: EngineErrorCode;
  constructor(code: EngineErrorCode, message: string) {
    super(message);
    this.name = 'EngineError';
    this.code = code;
  }
}

export interface EngineInfo {
  coreVersion: string;          // "1.0"
  solverVersion: number;        // cx::kSolverVersion (stepping results can change when bumped)
  snapshotSchema: number;       // cx::kSnapshotSchemaVersion (save bytes)
  build: string;                // emscripten version + flags
  /** What this build supports; see web/core/README.md for the coverage note. */
  capabilities: string[];
}

export interface SceneIssue {
  severity: 'info' | 'warning' | 'error';
  path: string;                 // JSON path, e.g. "bodies[3].mass_kg"
  message: string;
}

export interface LoadSceneOptions {
  /** Start paused (the UE client's default for opened places). Default true. */
  startPaused?: boolean;
}

export interface LoadSceneResult {
  sceneId: string;
  profile: string;              // Portable64 | Portable128 | Portable256 (chosen by massive-body count, as the UE client)
  bodiesLoaded: number;
  tracersSeeded: number;
  optionalBodiesAvailable: number;
  suggestedHorizon: number;     // s (0 = none)
  timeScaleHint: number;        // sim s per real s (0 = none)
  modeDefault: string;          // "A" | "D" (raw)
  capabilities: string[];       // activated by this scene
  keyToId: Record<string, number>;
  structureGroups: Record<string, number>; // structure id -> tracer group
  issues: SceneIssue[];         // warnings and infos (errors reject the request)
  snapshot: EngineSnapshot;
}

export interface BodyFlags {
  controversial: boolean;
  userEdited: boolean;
  fantasyOutcome: boolean;
  outsideValidity: boolean;     // exceeded the speed limit
}

export interface EngineBody {
  id: number;                   // core BodyId (never reused within one history; Undo/Redo can rebind, see historyRevision)
  key: string;                  // scene-local content id (NOT unique: two bodies may share it)
  name: string;
  kind: BodyKind;
  classTag: string;
  subclass: string;
  parentId: number;             // UI hierarchy only (0 = none)
  mass: number;                 // kg
  radius: number;               // m
  position: Vec3;               // m
  velocity: Vec3;               // m/s
  luminosity: number;           // W
  effectiveTemperature: number; // K (stars; informative)
  /** Radiative equilibrium temperature from the core's irradiance model (K); null for stars and compact objects. */
  equilibriumTemperature: number | null;
  surfaceTemperature: number | null; // K, with greenhouse depth
  stellarFlux: number | null;   // W/m^2 received
  bondAlbedo: number;
  greenhouseDepth: number;
  spinAxis: Vec3;
  spinRate: number;             // rad/s
  rotationAngle: number;        // rad
  schwarzschildRadius: number;  // m (all bodies; meaningful for compact ones)
  ring: { inner: number; outer: number; mass: number } | null;
  atmosphere: { surfacePressure: number; meanMolarMass: number } | null;
  appearanceProfile: string;
  appearanceSeed: number;
  hasSurface: boolean;
  flags: BodyFlags;
}

export interface EngineTracers {
  count: number;
  /** Tracer group per tracer (structures and seeded rings). */
  groups: Uint32Array;
  /** x0,y0,z0,x1,... in m. */
  positions: Float64Array;
}

export interface EngineEvent {
  sequence: number;             // core event sequence (repeats after Undo; use (worldId, historyRevision, sequence))
  kind: EngineEventKind;
  time: number;                 // s, the core event's own time (transits/eclipses: mid time)
  a: number;                    // body ids (0 = none)
  b: number;
  result: number;
  count: number;
  values: [number, number, number, number];
  worldId: number;              // identity of the world that produced it
  historyRevision: number;
}

export interface StepSummary {
  requestedSeconds: number;
  achievedSeconds: number;
  macroSteps: number;
  substeps: number;
  adaptiveMacroSteps: number;
  integrator: 'leapfrog_kdk' | 'adaptive_dp54' | 'hybrid';
  smallestSubstep: number;      // s, 0 if none
  collisions: number;
  limit: StepLimit;
}

export interface ConservationReport {
  totalMass: number;            // kg
  totalEnergy: number;          // J
  relativeEnergyError: number;
  relativeMomentumError: number;
  relativeAngularMomentumError: number;
  relativeMassError: number;
}

export interface GuardState {
  pending: boolean;
  compactId: number;
  intruderId: number;
  time: number;
  guardRadius: number;
}

export interface HistoryState {
  canUndo: boolean;
  canRedo: boolean;
  undoLabel: string;
  redoLabel: string;
  undoDepth: number;
  redoDepth: number;
}

export interface ObserverSummary {
  id: number;
  kind: 'photometer' | 'pulsar_receiver' | 'flux_receiver';
  targetId: number;
  totalSamples: number;
}

/** One atomic state of the live world, produced by the worker after a request or a playback slice. */
export interface EngineSnapshot {
  /** Monotonic per engine instance. A snapshot with a lower sequence is never newer. */
  sequence: number;
  /** +1 for every world replacement: loadScene, loadSave, switchBranch, reset. Ids are only comparable within one worldId. */
  worldId: number;
  /** Changes at every replacement, Undo and Redo (never repeats). Within one (worldId, historyRevision) an id names one body. */
  historyRevision: number;
  /** +1 for every applied change (edit, add, remove, step with collisions...). */
  editRevision: number;
  sceneId: string;
  simTime: number;              // s since the scene epoch
  epochJulianDate: number;      // display only
  stepCount: number;
  baseStep: number;             // s
  profile: string;
  run: RunState;
  playing: boolean;             // the worker's playback loop is active
  rate: number;                 // sim s per real s requested for playback
  guard: GuardState;
  bodies: EngineBody[];
  tracers: EngineTracers;
  /** Core events since the previous snapshot of this engine, in order. */
  events: EngineEvent[];
  history: HistoryState;
  branches: { active: string; stored: string[] };
  observers: ObserverSummary[];
  conservation: ConservationReport;
  stateHash: string;            // core StateHash v1 (physics only), 16 hex digits
  lastStep: StepSummary | null;
}

/** Partial body edit (cx::BodyPatch subset). Omitted fields are unchanged. */
export interface BodyPatch {
  name?: string;
  kind?: BodyKind;
  mass?: number;
  radius?: number;
  position?: Vec3;
  velocity?: Vec3;
  luminosity?: number;
  effectiveTemperature?: number;
  bondAlbedo?: number;
  greenhouseDepth?: number;
  spinAxis?: Vec3;
  spinRate?: number;
  appearanceProfile?: string;
  appearanceSeed?: number;
}

/**
 * New bodies use the scene body schema (the same objects as a scene document's "bodies" entries: id, name, class,
 * mass_kg, radius_m, state {...}, ...). They are validated by the core scene parser; parents may name keys of the same
 * batch or of bodies already in the world.
 */
export type SceneBodyJson = Record<string, unknown>;

export interface AddBodiesResult {
  createdIds: number[];
  snapshot: EngineSnapshot;
}

export interface ObserverRequest {
  targetId: number;             // the luminous source observed
  direction: Vec3;              // unit vector from the system towards the observer
  cadence?: number;             // s between samples
  exposure?: number;            // s
}

/** The engine, owned by the main thread; all work runs in a Web Worker. Every method rejects with EngineError. */
export interface EngineController {
  /** Resolves when the WebAssembly core is instantiated. */
  readonly ready: Promise<EngineInfo>;

  loadScene(sceneDocument: string | object, options?: LoadSceneOptions): Promise<LoadSceneResult>;
  /** Reload the last loaded scene document (a new worldId). */
  reset(): Promise<EngineSnapshot>;

  /**
   * Advance whole base steps toward simTime + seconds (core AdvanceTo). One bounded slice: at most maxSteps macro steps
   * (1..4096, default 4096) and the core's sub-step budget (200000); lastStep.limit says why it stopped ('budget' when
   * the slice ended first). The world must be running ('paused' otherwise); simTime + seconds must be finite.
   */
  step(seconds: number, maxSteps?: number): Promise<EngineSnapshot>;
  /** Exactly n whole base steps (core AdvanceScheduled), n in 1..4096 per request; split longer runs into requests. */
  stepExact(steps: number): Promise<EngineSnapshot>;
  pause(): Promise<EngineSnapshot>;
  resume(): Promise<EngineSnapshot>;
  /**
   * Worker-side real-time playback at rate sim-s per real-s: simulation-time debt accumulates and is stepped in whole base
   * steps (bounded slices, ~30 Hz); a rate below baseStep per slice steps once per baseStep of accumulated time. At most
   * 1 s of real time is caught up after a stall. Stops when the world stops running (guard, speed limit, fault).
   */
  play(rate: number): Promise<EngineSnapshot>;
  stop(): Promise<EngineSnapshot>;
  setBaseStep(seconds: number): Promise<EngineSnapshot>;

  editBody(id: number, patch: BodyPatch, label?: string): Promise<EngineSnapshot>;
  kick(id: number, deltaVelocity: Vec3, label?: string): Promise<EngineSnapshot>;
  addBodies(bodies: SceneBodyJson[], label?: string): Promise<AddBodiesResult>;
  removeBodies(ids: number[], label?: string): Promise<EngineSnapshot>;
  undo(): Promise<EngineSnapshot>;
  redo(): Promise<EngineSnapshot>;

  createBranch(name: string): Promise<EngineSnapshot>;
  switchBranch(name: string): Promise<EngineSnapshot>;

  addObserver(request: ObserverRequest): Promise<{ observerId: number; snapshot: EngineSnapshot }>;
  removeObserver(observerId: number): Promise<EngineSnapshot>;
  enableSurface(bodyId: number, latitudeBands?: number, longitudeCells?: number): Promise<EngineSnapshot>;

  /** Core snapshot bytes (cx::SaveSnapshot, schema snapshotSchema). Not the UE slot container. */
  save(): Promise<Uint8Array>;
  /** Restores core snapshot bytes as a new world (new worldId); refused atomically if corrupt or incompatible. */
  loadSave(bytes: Uint8Array): Promise<EngineSnapshot>;

  snapshot(): Promise<EngineSnapshot>;
  /** Every snapshot the worker posts (request results and playback). Returns an unsubscribe function. */
  subscribe(listener: (snapshot: EngineSnapshot) => void): () => void;
  dispose(): void;
}
